// ValidOutputFormats returns all valid output format values
func ValidOutputFormats() []string {
	return []string{string(OutputBlended), string(OutputByQuery), string(OutputByCollection)}
}

// Formatter handles output formatting with support for AXI, JSON and minimal modes.
type Formatter struct {
	JSON    bool // Output as JSON
	Minimal bool // Output in minimal/token-optimized mode
	AXI     bool // Output as TOON (AXI token-dense format)
	Writer  io.Writer
}

// IsValidOutputFormat checks if the given format string is valid
func IsValidOutputFormat(format string) bool {
	switch OutputFormat(format) {
	case OutputBlended, OutputByQuery, OutputByCollection:
		return true
	case "": // empty means default (blended)
		return true
	}
	return false
}

func TestFormatter_Print_JSON(t *testing.T) {
	var buf bytes.Buffer
	f := New(true, false, &buf)

	data := TestOutput{Name: "test", Count: 5}

	err := f.Print(data, nil)
	if err != nil {
		t.Fatalf("Print failed: %v", err)
	}

	output := buf.String()
	if !strings.Contains(output, "\"name\": \"test\"") {
		t.Errorf("Expected JSON output with name, got: %s", output)
	}
	if !strings.Contains(output, "\"count\": 5") {
		t.Errorf("Expected JSON output with count, got: %s", output)
	}
	// Should be pretty-printed (contains newlines)
	if !strings.Contains(output, "\n  ") {
		t.Errorf("Expected pretty-printed JSON, got: %s", output)
	}
}

func runRefs(ctx context.Context, symbol string, jsonOutput, minOutput bool) error {
	rs, cleanup, err := openRefStorage(ctx)
	if err != nil {
		return err
	}
	defer cleanup()

	return writeRefs(ctx, os.Stdout, rs, symbol, jsonOutput, minOutput)
}

// outputMode is one of the four ways a search command prints.
type outputMode struct {
	name       string
	json, min  bool
	axi        bool
	structured bool // stdout is JSON
}

func multisearchCmd() *cobra.Command {
	var (
		topK         int
		threshold    float64
		profiles     []string
		noBoost      bool
		noDedupe     bool
		outputFormat string
		jsonOutput   bool
		minOutput    bool
		full         bool
	)

	cmd := &cobra.Command{
		Use:   "multisearch <query1> [query2] [query3] ...",
		Short: "Execute multiple semantic queries with deduplication and boosting",
		Long: `Execute multiple semantic queries in parallel with intelligent deduplication and multi-match boosting.

Results matching multiple queries receive boosted scores (+0.05 per additional match).
Duplicate chunks are deduplicated, keeping the highest score.

Examples:
  llm-semantic multisearch "authentication" "JWT tokens"
  llm-semantic multisearch "error handling" "logging" --profiles code,docs
  llm-semantic multisearch "api endpoint" "REST handler" --top 20 --json
  llm-semantic multisearch "test" "spec" --output by_query`,
		Args: cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			queries := args

			// Validate queries
			if len(queries) > semantic.MaxQueries {
				return fmt.Errorf("multisearch supports up to %d queries, got: %d", semantic.MaxQueries, len(queries))
			}

			// Filter empty queries
			var filteredQueries []string
			for _, q := range queries {
				q = strings.TrimSpace(q)
				if q != "" {
					filteredQueries = append(filteredQueries, q)
				}
			}
			if len(filteredQueries) == 0 {
				return fmt.Errorf("at least one non-empty query required")
			}

			// Validate output format
			if outputFormat != "" && !semantic.IsValidOutputFormat(outputFormat) {
				return fmt.Errorf("invalid output format: %s (valid: %s)", outputFormat, strings.Join(semantic.ValidOutputFormats(), ", "))
			}

			// Validate profile names
			for _, p := range profiles {
				if !config.IsValidProfile(p) {
					return fmt.Errorf("invalid profile: %s (valid: %s)", p, strings.Join(config.ValidProfiles(), ", "))
				}
			}

			return runMultisearch(cmd.Context(), filteredQueries, multisearchOpts{
				topK:         topK,
				threshold:    float32(threshold),
				profiles:     profiles,
				noBoost:      noBoost,
				noDedupe:     noDedupe,
				outputFormat: semantic.OutputFormat(outputFormat),
				jsonOutput:   jsonOutput,
				minOutput:    minOutput,
				full:         full,
			})
		},
	}

	cmd.Flags().IntVarP(&topK, "top", "n", 15, "Maximum number of results to return (default 15 vs search's 10 to account for multi-query result merging)")
	cmd.Flags().Float64VarP(&threshold, "threshold", "t", 0.0, "Minimum similarity score (0.0-1.0)")
	cmd.Flags().StringSliceVar(&profiles, "profiles", nil, "Profiles to search across (comma-separated, e.g., code,docs)")
	cmd.Flags().BoolVar(&noBoost, "no-boost", false, "Disable multi-match score boosting")
	cmd.Flags().BoolVar(&noDedupe, "no-dedupe", false, "Disable result deduplication")
	cmd.Flags().StringVar(&outputFormat, "output", "", "Output format: blended (default), by_query, by_collection")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output results as JSON")
	cmd.Flags().BoolVar(&minOutput, "min", false, "Output minimal JSON format")
	cmd.Flags().BoolVar(&full, "full", false, "With --axi, return every field and the whole content of each result")

	return cmd
}

// writeCallers answers runCallers from an opened call graph view.
func writeCallers(ctx context.Context, w io.Writer, rs semantic.RefStorage, symbol string, jsonOutput, minOutput bool) error {
	edges, err := rs.GetCallersByName(ctx, symbol)
	if err != nil {
		return fmt.Errorf("failed to look up callers of %q: %w", symbol, err)
	}

	zero, err := diagnoseWhenUsed(ctx, rs, symbol, "callers of", len(edges), jsonOutput, minOutput)
	if err != nil {
		return err
	}

	stale := refStaleness(ctx, rs)
	return formatCallers(w, symbol, edges, zero, &stale, jsonOutput, minOutput)
}

func refsCmd() *cobra.Command {
	var (
		jsonOutput bool
		minOutput  bool
	)

	cmd := &cobra.Command{
		Use:   "refs <symbol>",
		Short: "Show what a symbol references",
		Long: `List the calls, imports and type references made by a symbol.

References to something outside the index, such as a standard library call, are
listed and marked external rather than dropped.

Example:
  llm-semantic refs ResolveRefs`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runRefs(cmd.Context(), args[0], jsonOutput, minOutput)
		},
	}

	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	cmd.Flags().BoolVar(&minOutput, "min", false, "Minimal output format")

	return cmd
}
